use vstd::prelude::*;

verus! {

fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> (result: Vec<u8>)
    requires 
        a.len() == b.len(),
        a.len() > 0,
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a@.len() ==> result@[i] == a@[i] ^ b@[i],
{
    let n = a.len();
    let mut result: Vec<u8> = Vec::new();
    let mut idx: usize = 0;
    while idx < n
        invariant
            idx <= n,
            n == a.len(),
            a.len() == b.len(),
            result.len() == idx,
            forall|i: int| 0 <= i < idx ==> result@[i] == a@[i] ^ b@[i],
        decreases n - idx,
    {
        result.push(a[idx] ^ b[idx]);
        idx += 1;
    }
    result
}

}
fn main() {}

use vstd::prelude::*;

verus! {
/* Matrix type definition - represents an m×n matrix */
pub struct Matrix<T> {
    pub data: Vec<Vec<T>>,
    pub rows: usize,
    pub cols: usize,
}

impl<T: Copy> Matrix<T> {
    pub open spec fn view(self) -> Seq<Seq<T>> {
        self.data@.map(|i: int, row: Vec<T>| row@)
    }

    pub open spec fn wf(self) -> bool {
        &&& self.data.len() == self.rows
        &&& forall|i: int| 0 <= i < self.data.len() ==> self.data[i].len() == self.cols
    }

    pub open spec fn index(self, i: int, j: int) -> T 
        recommends 0 <= i < self.rows && 0 <= j < self.cols && self.wf()
    {
        self.data[i][j]
    }

    pub open spec fn size(self) -> int {
        self.rows * self.cols
    }
}

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> (ret: Matrix<i8>)
    requires 
        a.len() > 0,
        shape.len() == 2,
        shape[0] > 0,
        shape[1] > 0,
        shape[0] as int == a.len() || shape[1] as int == a.len(),
    ensures
        ret.wf(),
        ret.rows == shape[0] as usize,
        ret.cols == shape[1] as usize,
        ret.size() == shape[0] as int * shape[1] as int,
        forall|i: int, j: int| 0 <= i < shape[0] as int && 0 <= j < shape[1] as int ==> {
            if shape[0] as int == a.len() {
                ret.index(i, j) == a[i as int]
            } else {
                ret.index(i, j) == a[j as int]
            }
        }
{
    let rows = shape[0] as usize;
    let cols = shape[1] as usize;
    let mut data: Vec<Vec<i8>> = Vec::new();
    let mut i: usize = 0;
    while i < rows
        invariant
            i <= rows,
            rows == shape[0] as usize,
            cols == shape[1] as usize,
            shape.len() == 2,
            shape[0] > 0,
            shape[1] > 0,
            shape[0] as int == a.len() || shape[1] as int == a.len(),
            a.len() > 0,
            data.len() == i,
            forall|k: int| 0 <= k < i ==> data[k].len() == cols,
            forall|k: int, j: int| 0 <= k < i && 0 <= j < cols as int ==> {
                if shape[0] as int == a.len() {
                    data[k][j] == a[k]
                } else {
                    data[k][j] == a[j]
                }
            },
        decreases rows - i,
    {
        let mut row: Vec<i8> = Vec::new();
        let mut j: usize = 0;
        while j < cols
            invariant
                j <= cols,
                rows == shape[0] as usize,
                cols == shape[1] as usize,
                shape.len() == 2,
                shape[0] > 0,
                shape[1] > 0,
                shape[0] as int == a.len() || shape[1] as int == a.len(),
                a.len() > 0,
                i < rows,
                row.len() == j,
                forall|jj: int| 0 <= jj < j ==> {
                    if shape[0] as int == a.len() {
                        row[jj] == a[i as int]
                    } else {
                        row[jj] == a[jj]
                    }
                },
            decreases cols - j,
        {
            if shape[0] as usize == a.len() {
                row.push(a[i]);
            } else {
                row.push(a[j]);
            }
            j += 1;
        }
        data.push(row);
        i += 1;
    }
    Matrix {
        data,
        rows,
        cols,
    }
}

}
fn main() {}

use vstd::prelude::*;

verus! {

fn copy(arr: &Vec<i8>) -> (result: Vec<i8>)
    ensures
        result.len() == arr.len(),
        forall|i: int| 0 <= i < arr.len() ==> result[i] as int == arr[i] as int,
{
    let mut result: Vec<i8> = Vec::new();
    let mut idx = 0;
    while idx < arr.len()
        invariant
            idx <= arr.len(),
            result.len() == idx,
            forall|i: int| 0 <= i < idx ==> result[i] as int == arr[i] as int,
        decreases arr.len() - idx,
    {
        result.push(arr[idx]);
        idx += 1;
    }
    result
}

}
