fn equal(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
    requires a.len() == b.len(),
    ensures 
        result.len() == a.len(),
        forall|i: int| 0 <= i < a@.len() ==> result@[i] == (a@[i] == b@[i])
{
    let mut result: Vec<bool> = Vec::new();
    let mut idx = 0;
    while idx < a.len()
        invariant
            idx <= a.len(),
            result.len() == idx,
            a.len() == b.len(),
            forall|i: int| 0 <= i < idx ==> result@[i] == (a@[i] == b@[i]),
        decreases a.len() - idx,
    {
        result.push(a[idx] == b[idx]);
        idx += 1;
    }
    result
}

}
