use vstd::prelude::*;

verus! {

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> (result: Vec<bool>)
    requires 
        a.len() > 0,
        a.len() == b.len(),
        tol > 0,
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==> 
            result[i] == (-(tol as int) < (a[i] as int) - (b[i] as int) && (a[i] as int) - (b[i] as int) < (tol as int)),
{
    let n = a.len();
    let mut result: Vec<bool> = Vec::new();
    let mut idx: usize = 0;
    while idx < n
        invariant
            idx <= n,
            n == a.len(),
            n == b.len(),
            result.len() == idx,
            tol > 0,
            forall|i: int| 0 <= i < idx ==>
                result[i] == (-(tol as int) < (a[i] as int) - (b[i] as int) && (a[i] as int) - (b[i] as int) < (tol as int)),
        decreases n - idx,
    {
        let ai = a[idx] as i32;
        let bi = b[idx] as i32;
        let diff = ai - bi;
        let tol_i32 = tol as i32;
        let close = -tol_i32 < diff && diff < tol_i32;
        result.push(close);
        idx += 1;
    }
    result
}

}
fn main() {}

