verus! {

fn less(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
    requires a.len() == b.len(),
    ensures 
        result.len() == a.len(),
        forall|i: int| 0 <= i < a@.len() ==> result@[i] == (a@[i] < b@[i])
{
    let n = a.len();
    let mut result: Vec<bool> = Vec::new();
    let mut idx: usize = 0;
    while idx < n
        invariant
            idx <= n,
            n == a.len(),
            n == b.len(),
            result.len() == idx,
            forall|i: int| 0 <= i < idx ==> result@[i] == (a@[i] < b@[i]),
        decreases n - idx,
    {
        result.push(a[idx] < b[idx]);
        idx += 1;
    }
    result
}

}
